class Solution {
public:
    int maxIceCream(vector<int>& costs, int coins) {
        const int MAX_PRICE = 100000;
        vector<int> count(MAX_PRICE + 1, 0);
        for (int c : costs) count[c]++;
        int ans = 0;
        for (int price = 1; price <= MAX_PRICE; price++) {
            if (count[price] == 0) continue;
            if (coins < price) break;
            int canBuy = min(count[price], coins / price);
            ans += canBuy;
            coins -= canBuy * price;
        }
        return ans;
    }
};
